// Golden parity with the Python desktop app (plan §8.1): the fixture
// tests/fixtures/golden.json is generated by scripts/gen_golden.py from the
// unmodified vibro modules. Tolerances: amplitudes 1e-6 (plan), stats 1e-9
// relative (double-precision summation order differences only).

import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { computeSpectrum } from "../../src/core/fft";
import { findPeaks } from "../../src/core/peaks";
import { rmsZeroCentered, vectorRms } from "../../src/core/stats";
import { DVB1_LSB_TO_MS2 } from "../../src/core/constants";

const fixtureDir = fileURLToPath(new URL("../fixtures", import.meta.url));
const golden = JSON.parse(readFileSync(`${fixtureDir}/golden.json`, "utf8")) as {
  window: number;
  dvb1_rate: number;
  live_fs: number;
  max_fft_points: number;
  full_freqs: number[];
  live_freqs: number[];
  bursts: Array<{
    burst: number;
    rms_total: number;
    axes: Record<
      "x" | "y" | "z",
      {
        rms: number;
        full: { amps: number[]; peaks: [number, number][] };
        live: { amps: number[]; peaks: [number, number][] };
      }
    >;
  }>;
};

const binBytes = readFileSync(`${fixtureDir}/test_data.bin`);
const raw = new Int16Array(binBytes.buffer, binBytes.byteOffset, binBytes.byteLength / 2);

function axisSamples(burst: number, axis: number): Float64Array {
  const base = burst * golden.window * 3;
  const out = new Float64Array(golden.window);
  for (let i = 0; i < golden.window; i++) {
    out[i] = raw[base + i * 3 + axis] * DVB1_LSB_TO_MS2;
  }
  // remove_gravity_component: subtract the mean (also done inside the FFT).
  let mean = 0;
  for (const v of out) mean += v;
  mean /= out.length;
  for (let i = 0; i < out.length; i++) out[i] -= mean;
  return out;
}

const AXES = ["x", "y", "z"] as const;

describe("golden parity (Python oracle)", () => {
  it("fixture covers all six test bursts", () => {
    expect(golden.bursts.length).toBe(6);
    expect(golden.window).toBe(6400);
    expect(golden.dvb1_rate).toBe(3200);
    expect(golden.live_fs).toBe(1600);
    expect(golden.max_fft_points).toBe(512);
  });

  for (const burst of golden.bursts) {
    describe(`burst ${burst.burst}`, () => {
      it("per-axis RMS and resultant match", () => {
        const rms: number[] = [];
        for (const axis of AXES) {
          const samples = axisSamples(burst.burst, AXES.indexOf(axis));
          const value = rmsZeroCentered(samples);
          const rel = Math.abs(value - burst.axes[axis].rms) / burst.axes[axis].rms;
          expect(rel).toBeLessThan(1e-9);
          rms.push(value);
        }
        const total = vectorRms(rms[0], rms[1], rms[2]);
        const rel = Math.abs(total - burst.rms_total) / burst.rms_total;
        expect(rel).toBeLessThan(1e-9);
      });

      it("full-burst FFT (n=6400, Bluestein) matches np.fft.rfft", () => {
        for (const axis of AXES) {
          const samples = axisSamples(burst.burst, AXES.indexOf(axis));
          const spec = computeSpectrum(samples, golden.dvb1_rate, true);
          const expected = burst.axes[axis].full.amps;
          expect(spec.amps.length).toBe(expected.length);
          let maxDiff = 0;
          for (let k = 0; k < expected.length; k++) {
            maxDiff = Math.max(maxDiff, Math.abs(spec.amps[k] - expected[k]));
          }
          expect(maxDiff).toBeLessThan(1e-6);
        }
      });

      it("live FFT (last 512 @ 1600 Hz) matches", () => {
        for (const axis of AXES) {
          const samples = axisSamples(burst.burst, AXES.indexOf(axis));
          const spec = computeSpectrum(samples, golden.live_fs, false, golden.max_fft_points);
          const expected = burst.axes[axis].live.amps;
          expect(spec.amps.length).toBe(expected.length);
          let maxDiff = 0;
          for (let k = 0; k < expected.length; k++) {
            maxDiff = Math.max(maxDiff, Math.abs(spec.amps[k] - expected[k]));
          }
          expect(maxDiff).toBeLessThan(1e-6);
        }
      });

      it("find_fft_peaks matches (top 3 bins, strongest first)", () => {
        for (const axis of AXES) {
          const samples = axisSamples(burst.burst, AXES.indexOf(axis));
          for (const mode of ["full", "live"] as const) {
            const spec =
              mode === "full"
                ? computeSpectrum(samples, golden.dvb1_rate, true)
                : computeSpectrum(samples, golden.live_fs, false, golden.max_fft_points);
            const peaks = findPeaks(spec.freqs, spec.amps);
            const expected = burst.axes[axis][mode].peaks;
            expect(peaks.length).toBe(expected.length);
            for (let i = 0; i < expected.length; i++) {
              expect(peaks[i].frequency).toBeCloseTo(expected[i][0], 9);
              expect(peaks[i].amplitude).toBeLessThan(1e-6 + expected[i][1]);
              expect(Math.abs(peaks[i].amplitude - expected[i][1])).toBeLessThan(1e-6);
            }
          }
        }
      });
    });
  }
});
